/**
 * Generic fallback glyph (a code chevron) used when a language has no dedicated
 * icon. Uses `currentColor` so it follows the surrounding text color.
 */
const fallbackGlyph = `<path fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" d="M12 10 6 16l6 6M20 10l6 6-6 6M18 8l-4 16"/>`;

/**
 * Build the full SVG element string for a language icon at a given size.
 *
 * @param language - the editor language identifier (a key of {@link codeLanguages}).
 * @param size - the width/height to render at (a CSS length or "100%").
 * @returns an `<svg>` element string.
 */
function buildLanguageIconSvg(language: string, size: string): string {
  const glyph = languageIconGlyphs[language] ?? fallbackGlyph;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="${size}" height="${size}" aria-hidden="true" focusable="false">${glyph}</svg>`;
}

/**
 * Get a ready-to-render SVG element string for a language's icon, falling back
 * to a generic code glyph when the language is unknown. The icon fills its
 * container, so size it via CSS on the parent element.
 *
 * @param language - the editor language identifier (a key of {@link codeLanguages}).
 * @returns an `<svg>` element string suitable for assigning to innerHTML.
 */
export function getCodeLanguageIcon(language: string): string {
  return buildLanguageIconSvg(language, "100%");
}

/**
 * Get a language icon encoded as a `data:` URI, suitable for an `<img>` `src`.
 * Used by static HTML/PDF export where decorations (and therefore the live
 * editor's title widget) are not rendered.
 *
 * @param language - the editor language identifier (a key of {@link codeLanguages}).
 * @returns a `data:image/svg+xml` URI string.
 */
export function getCodeLanguageIconDataUri(language: string): string {
  return `data:image/svg+xml,${encodeURIComponent(buildLanguageIconSvg(language, "18"))}`;
}
